#version 300 es
precision highp float;

const float NEAR= 1.;//camera planes
const float FOV= 1.25;
const float FAR= 512.;

const float EV= .9;//exposure

const float BIGNESS= 1.2;//particle size, pixels

const float ENTROPY= .003;//particle jitter
const float BUMP= .005;//as in bumpmap


#define len length
#define lerp mix
#define norm normalize
#define nmaps(v) (v*2.-1.)

float lum(vec3 c){ return dot(c,vec3(vec3(0.2126, 0.7152, 0.0722))); }



vec3 nse_3_3(vec3 v){
	uvec3 x= uvec3(v*4321.);
	const uint k = 1103515245U;
	x = ((x>>8U)^x.yzx)*k;
	x = ((x>>8U)^x.yzx)*k;
	return vec3(x)*(2.0/float(0xffffffffU))-1.;
}

uniform sampler2D u_tex;
#define tex(uv) (textureLod(u_tex, uv*vec2(1.,-1.)*.5+.5, 0.))

uniform float time;

vec3 f(vec3 p){
	//texture
	vec4 t= tex(p.xy);
	t= t*(t);
	t= 1.-t;

	//displace
	float l= lum(t.rgb);
	vec3 nse= nse_3_3(vec3( p+time/1024. ));
	p.xy+= l*nse.xy*ENTROPY;//flux
	p.z += l*BUMP;
	p.z*=.999;
	if(p.z>1.02)//hop
		p.z-= BUMP;

	//reset a few to persist snow and prevent decay
	if(nse.z>.9982){
		p.xy= nse.xy;
		p.z=-NEAR;
	}

	return p;
}

layout(location=0) in vec3 in_p;
out vec3 v_pos;
flat out vec4 v_col;
void main(){

	//worldspace
	vec3 p= in_p;
	p= f(p);
	v_pos= p;

	//viewspace far:+z up:+y
	vec4 v= vec4(p,1.);
	v.z+= NEAR;
	v.w= v.z*FOV;
	//v.y-= 1./(1.+8.*v.w);
	v.w= sqrt(sqrt(v.w));//nonlinear perspective, feels deeper
	v.z/= FAR;
  gl_Position= v;//renegade lack of mvp

	float r= BIGNESS/v.w;
	float ps;
	float l=1.;
	if(r>1.)
		ps= min(24., r);
	else{
		l= r*r;//apparent irradiance
		ps= 1.;
	}
  gl_PointSize= ps;

	vec4 col= tex(p.xy);

	col.a= 1.;
	col.a*= EV*l;
	v_col= col;
}


